async (page) => {
  const input = page.getByPlaceholder('What needs to be done?');
  const results = {};
  // empty submit
  await input.press('Enter');
  results.afterEmptyEnter = await page.getByTestId('todo-item').count();
  // whitespace only
  await input.fill('     ');
  await input.press('Enter');
  results.afterWhitespaceEnter = await page.getByTestId('todo-item').count();
  results.inputValueAfterWhitespace = await input.inputValue();
  // leading/trailing whitespace
  await input.fill('   padded todo   ');
  await input.press('Enter');
  results.titles = await page.getByTestId('todo-title').allTextContents();
  results.storage = await page.evaluate(() => localStorage.getItem('react-todos'));
  results.inputValueAfterAdd = await input.inputValue();
  return results;
}

