async (page) => {
  const r = {};
  const item = page.getByTestId('todo-item').filter({ hasText: 'padded todo' });
  await item.dblclick();
  r.classDuringEdit = await item.getAttribute('class');
  const edit = item.getByRole('textbox', { name: 'Edit' });
  r.editVisible = await edit.isVisible();
  r.editValue = await edit.inputValue();
  r.editFocused = await edit.evaluate(el => el === document.activeElement);
  // Escape cancels
  await edit.fill('changed');
  await edit.press('Escape');
  r.afterEscape = await page.getByTestId('todo-title').allTextContents();
  r.classAfterEscape = await item.getAttribute('class');
  // Enter saves, with trimming
  await item.dblclick();
  await item.getByRole('textbox', { name: 'Edit' }).fill('   edited via enter   ');
  await item.getByRole('textbox', { name: 'Edit' }).press('Enter');
  r.afterEnter = await page.getByTestId('todo-title').allTextContents();
  return r;
}

