async (page) => {
  const r = {};
  const input = page.getByPlaceholder('What needs to be done?');
  for (const t of ['walk the dog', 'write tests']) { await input.fill(t); await input.press('Enter'); }
  r.titles = await page.getByTestId('todo-title').allTextContents();
  r.count3 = await page.getByTestId('todo-count').textContent();
  // whitespace-only edit
  const item = page.getByTestId('todo-item').filter({ hasText: 'walk the dog' });
  await item.dblclick();
  await item.getByRole('textbox', { name: 'Edit' }).fill('    ');
  await item.getByRole('textbox', { name: 'Edit' }).press('Enter');
  r.afterWhitespaceEdit = await page.getByTestId('todo-title').allTextContents();
  // complete one
  const first = page.getByTestId('todo-item').filter({ hasText: 'buy milk' });
  await first.getByRole('checkbox', { name: 'Toggle Todo' }).check();
  r.classAfterComplete = await first.getAttribute('class');
  r.countAfterComplete = await page.getByTestId('todo-count').textContent();
  r.clearCompletedVisible = await page.getByRole('button', { name: 'Clear completed' }).isVisible();
  r.footerHtml = await page.locator('.footer').innerHTML();
  return r;
}

