async (page) => {
  const r = {};
  const titles = () => page.getByTestId('todo-title').allTextContents();
  await page.getByRole('link', { name: 'Active' }).click();
  r.activeUrl = page.url(); r.activeTitles = await titles();
  r.activeSelectedClass = await page.getByRole('link', { name: 'Active' }).getAttribute('class');
  await page.getByRole('link', { name: 'Completed' }).click();
  r.completedUrl = page.url(); r.completedTitles = await titles();
  r.countVisibleOnCompleted = await page.getByTestId('todo-count').textContent();
  // deep link direct navigation
  await page.goto('https://demo.playwright.dev/todomvc/#/active');
  r.deepLinkActive = await titles();
  // reload persistence
  await page.goto('https://demo.playwright.dev/todomvc/#/');
  await page.reload();
  r.afterReload = await titles();
  r.afterReloadCount = await page.getByTestId('todo-count').textContent();
  r.completedClasses = await page.getByTestId('todo-item').evaluateAll(els => els.map(e => e.className));
  // toggle all
  const toggleAll = page.getByLabel('Mark all as complete');
  await toggleAll.check();
  r.afterToggleAllCount = await page.getByTestId('todo-count').textContent();
  r.afterToggleAllClasses = await page.getByTestId('todo-item').evaluateAll(els => els.map(e => e.className));
  r.toggleAllChecked = await toggleAll.isChecked();
  await toggleAll.uncheck();
  r.afterUncheckAllClasses = await page.getByTestId('todo-item').evaluateAll(els => els.map(e => e.className));
  r.afterUncheckCount = await page.getByTestId('todo-count').textContent();
  return r;
}

